def is_valid_password(pw):
    if len(pw) >= 8:
        return True
    for ch in pw:
        if ch.isdigit():
            return True
    return False

def dedupe(items):
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            result.append(item)
    return result
